-- name: SetAccountPaymentProcessorCustomerID :execrows
UPDATE identity_accounts SET
	payment_processor_customer_id = sqlc.arg(payment_processor_customer_id),
	last_updated_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND id = sqlc.arg(id)
	AND scope = sqlc.arg(scope);

-- name: MarkAccountBillingSynced :execrows
UPDATE identity_accounts SET
	last_payment_provider_synced_at = sqlc.narg(last_payment_provider_synced_at),
	last_updated_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND id = sqlc.arg(id)
	AND scope = sqlc.arg(scope);

-- name: AnswerInvitation :execrows
UPDATE identity_invitations SET
	status = sqlc.arg(status),
	status_note = sqlc.arg(status_note),
	to_user = sqlc.narg(to_user),
	last_updated_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND id = sqlc.arg(id)
	AND scope = sqlc.arg(scope)
	AND status = sqlc.arg(current_status);

-- name: RecordUserTermsOfServiceAgreement :execrows
UPDATE identity_users SET
	last_accepted_terms_of_service = sqlc.narg(last_accepted_terms_of_service),
	last_updated_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND id = sqlc.arg(id)
	AND scope = sqlc.arg(scope);

-- name: RecordUserPrivacyPolicyAgreement :execrows
UPDATE identity_users SET
	last_accepted_privacy_policy = sqlc.narg(last_accepted_privacy_policy),
	last_updated_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND id = sqlc.arg(id)
	AND scope = sqlc.arg(scope);

-- name: EraseUser :execrows
DELETE FROM identity_users
WHERE id = sqlc.arg(id)
	AND scope = sqlc.arg(scope);

-- name: DeleteUserRoles :execrows
DELETE FROM identity_user_roles
WHERE user_id = sqlc.arg(user_id);

-- name: InsertUserRole :exec
INSERT INTO identity_user_roles (
	user_id,
	role
) VALUES (
	sqlc.arg(user_id),
	sqlc.arg(role)
);

-- name: DeleteMembershipRoles :execrows
DELETE FROM identity_membership_roles
WHERE membership_id = sqlc.arg(membership_id);

-- name: InsertMembershipRole :exec
INSERT INTO identity_membership_roles (
	membership_id,
	role
) VALUES (
	sqlc.arg(membership_id),
	sqlc.arg(role)
);

-- name: DeleteInvitationRoles :execrows
DELETE FROM identity_invitation_roles
WHERE invitation_id = sqlc.arg(invitation_id);

-- name: InsertInvitationRole :exec
INSERT INTO identity_invitation_roles (
	invitation_id,
	role
) VALUES (
	sqlc.arg(invitation_id),
	sqlc.arg(role)
);

-- name: UpsertMembership :exec
INSERT INTO identity_memberships (
	id,
	scope,
	belongs_to_user,
	belongs_to_account,
	default_account
) VALUES (
	sqlc.arg(id),
	sqlc.arg(scope),
	sqlc.arg(belongs_to_user),
	sqlc.arg(belongs_to_account),
	sqlc.arg(default_account)
)
ON CONFLICT (belongs_to_user, belongs_to_account) DO UPDATE SET
	default_account = EXCLUDED.default_account,
	archived_at = NULL,
	last_updated_at = CURRENT_TIMESTAMP;

-- name: SetMembershipDefaultAccount :execrows
UPDATE identity_memberships SET
	default_account = sqlc.arg(default_account),
	last_updated_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND scope = sqlc.arg(scope)
	AND belongs_to_user = sqlc.arg(belongs_to_user)
	AND belongs_to_account = sqlc.arg(belongs_to_account);

-- name: ClearMembershipDefaultAccountsForUser :execrows
UPDATE identity_memberships SET
	default_account = sqlc.arg(default_account),
	last_updated_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND scope = sqlc.arg(scope)
	AND belongs_to_user = sqlc.arg(belongs_to_user)
	AND default_account <> sqlc.arg(default_account)
	AND belongs_to_account <> COALESCE(sqlc.narg(except_account_id), '');

-- name: ClearMembershipDefaultAccountsForAccount :execrows
UPDATE identity_memberships SET
	default_account = sqlc.arg(default_account),
	last_updated_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND scope = sqlc.arg(scope)
	AND belongs_to_account = sqlc.arg(belongs_to_account)
	AND default_account <> sqlc.arg(default_account);

-- name: ArchiveMembership :execrows
UPDATE identity_memberships SET
	archived_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND scope = sqlc.arg(scope)
	AND belongs_to_user = sqlc.arg(belongs_to_user)
	AND belongs_to_account = sqlc.arg(belongs_to_account);

-- name: ArchiveMembershipsForUser :execrows
UPDATE identity_memberships SET
	archived_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND scope = sqlc.arg(scope)
	AND belongs_to_user = sqlc.arg(belongs_to_user);

-- name: ArchiveMembershipsForAccount :execrows
UPDATE identity_memberships SET
	archived_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND scope = sqlc.arg(scope)
	AND belongs_to_account = sqlc.arg(belongs_to_account);
